internal val COUNTRY_NAMES_ML: String =
    "root\u001F01അൻഡോറ\u001Eയുണൈറ്റഡ് അറബ് എമിറൈറ്റ്‌സ്\u001Eഅഫ്‌ഗാനിസ്ഥാൻ\u001Eആൻറിഗ്വയും ബർബുഡയും\u001Eആൻഗ്വില്ല\u001Eഅൽബേനിയ\u001Eഅർമേനിയ\u001Eഅംഗോള\u001Eഅന്റാർട്ടിക്ക\u001Eഅർജന്റീന\u001Eഅമേരിക്കൻ സമോവ\u001Eഓസ്ട്രിയ\u001Eഓസ്‌ട്രേലിയ\u001Eഅറൂബ\u001Eഅലൻഡ് ദ്വീപുകൾ\u001Eഅസർബൈജാൻ\u001Eബോസ്നിയയും ഹെർസഗോവിനയും\u001Eബാർബഡോസ്\u001Eബംഗ്ലാദേശ്\u001Eബെൽജിയം\u001Eബർക്കിന ഫാസോ\u001Eബൾഗേറിയ\u001Eബഹ്റിൻ\u001Eബറുണ്ടി\u001Eബെനിൻ\u001Eസെന്റ് ബാർത്തലമി\u001Eബർമുഡ\u001Eബ്രൂണൈ\u001Eബൊളീവിയ\u001Eകരീബിയൻ നെതർലാൻഡ്സ്\u001Eബ്രസീൽ\u001Eബഹാമാസ്\u001Eഭൂട്ടാൻ\u001Eബൗവെട്ട് ദ്വീപ്\u001Eബോട്സ്വാന\u001Eബെലറൂസ്\u001Eബെലീസ്\u001Eകാനഡ\u001Eകോക്കസ് (കീലിംഗ്) ദ്വീപുകൾ\u001Eകോംഗോ - കിൻഷാസ\u001Eസെൻട്രൽ ആഫ്രിക്കൻ റിപ്പബ്ലിക്ക്\u001Eകോംഗോ - ബ്രാസവില്ലി\u001Eസ്വിറ്റ്സർലാൻഡ്\u001Eകോട്ട് ഡി വാർ\u001Eകുക്ക് ദ്വീപുകൾ\u001Eചിലി\u001Eകാമറൂൺ\u001Eചൈന\u001Eകൊളംബിയ\u001Eകോസ്റ്ററിക്ക\u001Eക്യൂബ\u001Eകേപ്പ് വേർഡ്\u001Eകുറാകാവോ\u001Eക്രിസ്മസ് ദ്വീപ്\u001Eസൈപ്രസ്\u001Eചെക്കിയ\u001Eജർമ്മനി\u001Eജിബൂത്തി\u001Eഡെൻമാർക്ക്\u001Eഡൊമിനിക്ക\u001Eഡൊമിനിക്കൻ റിപ്പബ്ലിക്ക്\u001Eഅൾജീരിയ\u001Eഇക്വഡോർ\u001Eഎസ്റ്റോണിയ‍\u001Eഈജിപ്ത്\u001Eപശ്ചിമ സഹാറ\u001Eഎറിത്രിയ\u001Eസ്‌പെയിൻ\u001Eഎത്യോപ്യ\u001Eഫിൻലാൻഡ്\u001Eഫിജി\u001Eഫാക്ക്‌ലാന്റ് ദ്വീപുകൾ\u001Eമൈക്രോനേഷ്യ\u001Eഫറോ ദ്വീപുകൾ\u001Eഫ്രാൻസ്\u001Eഗാബൺ\u001Eയുണൈറ്റഡ് കിംഗ്ഡം\u001Eഗ്രനേഡ\u001Eജോർജ്ജിയ\u001Eഫ്രഞ്ച് ഗയാന\u001Eഗേൺസി\u001Eഘാന\u001Eജിബ്രാൾട്ടർ\u001Eഗ്രീൻലൻഡ്\u001Eഗാംബിയ\u001Eഗിനിയ\u001Eഗ്വാഡലൂപ്പ്\u001Eഇക്വറ്റോറിയൽ ഗിനിയ\u001Eഗ്രീസ്\u001Eദക്ഷിണ ജോർജ്ജിയയും ദക്ഷിണ സാൻഡ്‌വിച്ച് ദ്വീപുകളും\u001Eഗ്വാട്ടിമാല\u001Eഗ്വാം\u001Eഗിനിയ-ബിസൗ\u001Eഗയാന\u001Eഹോങ്കോങ് (SAR) ചൈന\u001Eഹേർഡ്, മക്ഡോണൾഡ് ദ്വീപുകൾ\u001Eഹോണ്ടുറാസ്\u001Eക്രൊയേഷ്യ\u001Eഹെയ്തി\u001Eഹംഗറി\u001Eഇന്തോനേഷ്യ\u001Eഅയർലൻഡ്\u001Eഇസ്രായേൽ\u001Eഐൽ ഓഫ് മാൻ\u001Eഇന്ത്യ\u001Eബ്രിട്ടീഷ് ഇന്ത്യൻ ഓഷ്യൻ ടെറിട്ടറി\u001Eഇറാഖ്\u001Eഇറാൻ\u001Eഐസ്‌ലാന്റ്\u001Eഇറ്റലി\u001Eജേഴ്സി\u001Eജമൈക്ക\u001Eജോർദ്ദാൻ\u001Eജപ്പാൻ\u001Eകെനിയ\u001Eകിർഗിസ്ഥാൻ\u001Eകംബോഡിയ\u001Eകിരിബാട്ടി\u001Eകോമൊറോസ്\u001Eസെന്റ് കിറ്റ്‌സും നെവിസും\u001Eഉത്തരകൊറിയ\u001Eദക്ഷിണകൊറിയ\u001Eകുവൈറ്റ്\u001Eകേയ്മാൻ ദ്വീപുകൾ\u001Eകസാഖിസ്ഥാൻ\u001Eലാവോസ്\u001Eലെബനൻ\u001Eസെന്റ് ലൂസിയ\u001Eലിച്ചൺസ്റ്റൈൻ\u001Eശ്രീലങ്ക\u001Eലൈബീരിയ\u001Eലെസോതോ\u001Eലിത്വാനിയ\u001Eലക്സംബർഗ്\u001Eലാറ്റ്വിയ\u001Eലിബിയ\u001Eമൊറോക്കൊ\u001Eമൊണാക്കോ\u001Eമൾഡോവ\u001Eമോണ്ടെനെഗ്രോ\u001Eസെന്റ് മാർട്ടിൻ\u001Eമഡഗാസ്കർ\u001Eമാർഷൽ ദ്വീപുകൾ\u001Eനോർത്ത് മാസിഡോണിയ\u001Eമാലി\u001Eമ്യാൻമാർ (ബർമ്മ)\u001Eമംഗോളിയ\u001Eമക്കാവു എസ്.എ.ആർ. ചൈന\u001Eഉത്തര മറിയാനാ ദ്വീപുകൾ\u001Eമാർട്ടിനിക്ക്\u001Eമൗറിറ്റാനിയ\u001Eമൊണ്ടെസരത്ത്\u001Eമാൾട്ട\u001Eമൗറീഷ്യസ്\u001Eമാലിദ്വീപ്\u001Eമലാവി\u001Eമെക്സിക്കോ\u001Eമലേഷ്യ\u001Eമൊസാംബിക്ക്\u001Eനമീബിയ\u001Eന്യൂ കാലിഡോണിയ\u001Eനൈജർ\u001Eനോർഫോക് ദ്വീപ്\u001Eനൈജീരിയ\u001Eനിക്കരാഗ്വ\u001Eനെതർലാൻഡ്‌സ്\u001Eനോർവെ\u001Eനേപ്പാൾ\u001Eനൗറു\u001Eന്യൂയി\u001Eന്യൂസിലൻഡ്\u001Eഒമാൻ\u001Eപനാമ\u001Eപെറു\u001Eഫ്രഞ്ച് പോളിനേഷ്യ\u001Eപാപ്പുവ ന്യൂ ഗിനിയ\u001Eഫിലിപ്പീൻസ്\u001Eപാക്കിസ്ഥാൻ\u001Eപോളണ്ട്\u001Eസെന്റ് പിയറി ആൻഡ് മിക്വലൻ\u001Eപിറ്റ്‌കെയ്‌ൻ ദ്വീപുകൾ\u001Eപോർട്ടോ റിക്കോ\u001Eപാലസ്‌തീൻ പ്രദേശങ്ങൾ\u001Eപോർച്ചുഗൽ\u001Eപലാവു\u001Eപരാഗ്വേ\u001Eഖത്തർ\u001Eറീയൂണിയൻ\u001Eറൊമാനിയ\u001Eസെർബിയ\u001Eറഷ്യ\u001Eറുവാണ്ട\u001Eസൗദി അറേബ്യ\u001Eസോളമൻ ദ്വീപുകൾ\u001Eസീഷെൽസ്\u001Eസുഡാൻ\u001Eസ്വീഡൻ\u001Eസിംഗപ്പൂർ\u001Eസെന്റ് ഹെലീന\u001Eസ്ലോവേനിയ\u001Eസ്വാൽബാഡും ജാൻ മായേനും\u001Eസ്ലോവാക്യ\u001Eസിയെറ ലിയോൺ\u001Eസാൻ മറിനോ\u001Eസെനഗൽ\u001Eസോമാലിയ\u001Eസുരിനാം\u001Eദക്ഷിണ സുഡാൻ\u001Eസാവോ ടോമും പ്രിൻസിപെയും\u001Eഎൽ സാൽവദോർ\u001Eസിന്റ് മാർട്ടെൻ\u001Eസിറിയ\u001Eസ്വാസിലൻഡ്\u001Eടർക്ക്‌സും കെയ്‌ക്കോ ദ്വീപുകളും\u001Eഛാഡ്\u001Eഫ്രഞ്ച് ദക്ഷിണ ഭൂപ്രദേശം\u001Eടോഗോ\u001Eതായ്‌ലാൻഡ്\u001Eതാജിക്കിസ്ഥാൻ\u001Eടോക്കെലൂ\u001Eതിമോർ-ലെസ്റ്റെ\u001Eതുർക്ക്മെനിസ്ഥാൻ\u001Eടുണീഷ്യ\u001Eടോംഗ\u001Eതുർക്കിയെ\u001Eട്രിനിഡാഡും ടുബാഗോയും\u001Eടുവാലു\u001Eതായ്‌വാൻ\u001Eടാൻസാനിയ\u001Eഉക്രെയ്‌ൻ\u001Eഉഗാണ്ട\u001Eയു.എസ്. ദ്വീപസമൂഹങ്ങൾ\u001Eഅമേരിക്കൻ ഐക്യനാടുകൾ\u001Eഉറുഗ്വേ\u001Eഉസ്‌ബെക്കിസ്ഥാൻ\u001Eവത്തിക്കാൻ\u001Eസെന്റ് വിൻസെന്റും ഗ്രനെഡൈൻസും\u001Eവെനിസ്വേല\u001Eബ്രിട്ടീഷ് വെർജിൻ ദ്വീപുകൾ\u001Eയു.എസ്. വെർജിൻ ദ്വീപുകൾ\u001Eവിയറ്റ്നാം\u001Eവന്വാതു\u001Eവാലിസ് ആന്റ് ഫ്യൂച്യുന\u001Eസമോവ\u001Eയെമൻ\u001Eമയോട്ടി\u001Eദക്ഷിണാഫ്രിക്ക\u001Eസാംബിയ\u001Eസിംബാബ്‌വേ"

